# name: participant_side_bias_variance
# description: Variance across participants of each participant's proportion of LEFT choices; observed above null_mean means individuals carry personal side (button) biases the model, which has no per-person side term, under-produces.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().var())

# name: left_choice_rate
# description: Overall proportion of trials on which the LEFT sequence was chosen; observed above null_mean means people have a left-side bias the (side-symmetric) model under-produces, below means a right-side bias.
def test_statistic(df):
    return float(df["chose_left"].mean())

# name: periodic_motif_choice
# description: Among trials where exactly one sequence is a repeated block of period 3 or 4 (e.g. HHTHHT, HHTTHHTT, length >= twice the period, not perfectly alternating), the proportion choosing the periodic one; observed below null_mean means people detect and penalise repeating motifs beyond what the model's run/switch features predict.
def test_statistic(df):
    def periodic(s):
        n = len(s)
        if all(x != y for x, y in zip(s, s[1:])) or len(set(s)) < 2:
            return False
        for p in (3, 4):
            if n >= 2 * p and all(s[i] == s[i - p] for i in range(p, n)):
                return True
        return False
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    pf = {s: periodic(s) for s in seqs}
    pa = df["sequence_a"].map(pf).to_numpy(dtype=bool)
    pb = df["sequence_b"].map(pf).to_numpy(dtype=bool)
    y = df["chose_left"].to_numpy()
    m = pa != pb
    if m.sum() == 0:
        return 0.5
    return float(np.where(pa[m], y[m], 1 - y[m]).mean())

# name: longer_initial_run_choice
# description: Among trials whose sequences differ in the length of their OPENING run (identical flips at the start), the proportion choosing the sequence with the longer opening run; observed below null_mean means people penalise opening streaks more than the model (which weights only the final and longest runs) predicts, above means less.
def test_statistic(df):
    def first_run(s):
        c = 1
        while c < len(s) and s[c] == s[0]:
            c += 1
        return c
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    fr = {s: first_run(s) for s in seqs}
    ra = df["sequence_a"].map(fr).to_numpy()
    rb = df["sequence_b"].map(fr).to_numpy()
    y = df["chose_left"].to_numpy()
    m = ra != rb
    if m.sum() == 0:
        return 0.5
    return float(np.where(ra[m] > rb[m], y[m], 1 - y[m]).mean())

# name: perfect_alternation_choice
# description: Among trials where exactly one sequence is perfectly alternating (every flip switches, length >= 4), the proportion choosing the perfectly alternating one; observed below null_mean means people reject strict alternation more than the model's (leniently weighted, quadratic) over-alternation penalty predicts, above means they accept it more.
def test_statistic(df):
    def perfect(s):
        return len(s) >= 4 and all(x != y for x, y in zip(s, s[1:]))
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    pf = {s: perfect(s) for s in seqs}
    pa = df["sequence_a"].map(pf).to_numpy(dtype=bool)
    pb = df["sequence_b"].map(pf).to_numpy(dtype=bool)
    y = df["chose_left"].to_numpy()
    m = pa != pb
    if m.sum() == 0:
        return 0.5
    return float(np.where(pa[m], y[m], 1 - y[m]).mean())
